import {lessons,tasks,LEVELS,initialState,cleanState,submitAnswer,revealSolution,progress,lessonSolved,nextLesson} from './course.js';
const KEY='cpp-junior-progress-v1';
let state,storageOK=true;
try{state=cleanState(JSON.parse(localStorage.getItem(KEY)))}catch{state=initialState();try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false}}
let view='today',activeLesson=Math.max(0,nextLesson(state)),activeTask=0,running=false,lastTick=Date.now(),feedback=null,saveTimeout;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v7a4 4 0 0 0 4 4h1m7-1V9a4 4 0 0 0-4-4h-1"/>',chart:'<path d="M4 4v16h16M8 15v-3m5 3V8m5 7V5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',book:'<path d="M12 5v15M3 4c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 1-3-2-6-2-9-1z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',flag:'<path d="M5 22V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8z"/>',bulb:'<path d="M9 18h6m-6 3h6M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>'}[name]||'')}</svg>`;
function dateKey(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Saratov',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Прогресс не удалось сохранить. Разреши хранение данных в браузере.');$('#storage-warning')?.removeAttribute('hidden')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function streak(){let d=new Date(dateKey()+'T12:00:00+04:00'),n=0;if(!state.days[dateKey(d)])d.setUTCDate(d.getUTCDate()-1);while(state.days[dateKey(d)]){n++;d.setUTCDate(d.getUTCDate()-1)}return n}
const done=(l)=>lessonSolved(state,l);
function setView(next){view=next;feedback=null;running=false;render();window.scrollTo({top:0,behavior:'instant'})}
function openLesson(i){activeLesson=i;activeTask=Math.max(0,lessons[i].tasks.findIndex(t=>!state.answers[t.id]?.solved));view='practice';running=true;lastTick=Date.now();feedback=null;render();window.scrollTo({top:0,behavior:'instant'})}
function shell(content){const p=progress(state);return `<aside class="sidebar"><a class="brand" href="#" data-nav="today"><span class="brand-mark">C<span>++</span></span><span>C++ Junior<small>ПРАКТИКА КАЖДЫЙ ДЕНЬ</small></span></a><div class="nav-label">ТВОЯ УЧЁБА</div><nav aria-label="Основная навигация">${[['today','sun','Сегодня'],['roadmap','route','Карта пути'],['stats','chart','Мой прогресс']].map(([v,i,t])=>`<button class="nav-item ${view===v||(view==='practice'&&v==='today')?'active':''}" data-nav="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}${t}${v==='roadmap'?'<span class="nav-count">9</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-level"><div class="level-seed">${icon('spark')}</div><div><strong>${LEVELS[p.level].name}</strong><small>Уровень ${p.level+1} · ${p.xp} XP</small></div></div><div class="mini-track"><i style="width:${p.percent}%"></i></div><p>${p.solved} из 27 задач до Junior</p><div class="private-note">${icon('lock')} Личный тренажёр</div></div></aside><div class="workspace"><header class="topbar"><span class="top-label">МАЛЕНЬКИЕ ШАГИ. БОЛЬШИЕ ВОЗМОЖНОСТИ.</span><span class="top-right"><span class="streak">${icon('bolt')} ${streak()} дн. подряд</span><span class="avatar" title="Твой профиль">C</span></span></header><main id="main" tabindex="-1"><div id="storage-warning" class="storage-warning" ${storageOK?'hidden':''}>Сохранение в браузере недоступно. Прогресс сохранится только до закрытия страницы.</div>${content}</main><footer><span>C++ Junior <span class="footer-dot">·</span> один час ближе к цели</span><span>Прогресс хранится в этом браузере <span class="saved-dot"></span></span></footer></div>`}
function weekly(){const today=new Date(dateKey()+'T12:00:00+04:00');const day=(today.getUTCDay()+6)%7;return Array.from({length:7},(_,i)=>{const d=new Date(today);d.setUTCDate(d.getUTCDate()-day+i);const k=dateKey(d),yes=state.days[k];return `<div class="week-day ${yes?'studied':''} ${k===dateKey()?'current':''}"><span>${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][i]}</span><div title="${k}: ${yes?'была практика':'без практики'}">${yes?icon('check'):d.getUTCDate()}</div></div>`}).join('')}
function todayPage(){const p=progress(state),n=nextLesson(state),i=n<0?8:n,l=lessons[i],all=n<0;return `<div class="page-intro"><div><p class="eyebrow">${new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Saratov',day:'numeric',month:'long',weekday:'long'}).format(new Date())}</p><h1>Твой следующий шаг в C++<span class="title-dot">.</span></h1><p class="muted">Один час в день. От первой переменной — к уверенным основам.</p></div><span class="outline-tag">${icon('lock')} Только для тебя</span></div><div class="home-grid"><section class="today-hero"><div class="hero-top"><span class="lime-pill">${all?'БАЗОВЫЙ МАРШРУТ ПРОЙДЕН':'ТВОЁ ЗАНЯТИЕ НА СЕГОДНЯ'}</span><span class="lesson-number">${String(i+1).padStart(2,'0')} <span>/ 09</span></span></div><div class="hero-body"><p class="hero-topic">${l.topic.toUpperCase()}</p><h2>${all?'Отличный фундамент.\nПродолжай практику.':l.title}</h2><p>${all?'Все 27 задач решены. Повтори сложные места и переходи к новым темам.':l.subtitle+'. Разберись, попробуй, проверь себя.'}</p></div><div class="hero-decoration" aria-hidden="true"><div class="code-orbit">{<span>++</span>}</div><span class="orbit-dot d1"></span><span class="orbit-dot d2"></span></div><div class="hero-bottom"><button class="btn btn-lime" data-open="${i}">${all?'Повторить занятие':done(l)>0?'Продолжить занятие':'Начать занятие'} ${icon('arrow')}</button><span>${icon('clock')} ~60 мин <b>·</b> ${done(l)}/3 задачи</span></div></section><section class="goal-card card"><div class="section-label">БОЛЬШАЯ ЦЕЛЬ ${icon('flag')}</div><div class="goal-title">Твой путь до <span>Junior</span></div><p class="muted small">Базовый рубеж: переменные,<br>условия и циклы.</p><div class="goal-progress"><strong>${p.percent}<small>%</small></strong><span>${p.xp} / 1350 XP</span></div><div class="progress-track"><i style="width:${p.percent}%"></i></div><div class="goal-foot"><span>${p.solved} / 27 задач</span><span>Уровень ${p.level+1} из 6</span></div></section><section class="plan-card card"><div class="section-heading"><h2>Твой план на час</h2><span>Ритм важнее скорости</span></div><div class="hour-plan">${[['01','book','Разобраться','10 мин','Прочитай короткую теорию'],['02','code','Попрактиковаться','40 мин','Реши три задачи в своём темпе'],['03','spark','Закрепить','10 мин','Разбери ошибки и повтори выводы']].map(([n,ic,title,time,sub])=>`<div class="plan-step"><span class="step-icon">${icon(ic)}</span><span class="step-no">${n}</span><h3>${title}</h3><p>${sub}</p><span class="time-label">${time}</span></div>`).join('')}</div></section><section class="week-card card"><div class="section-heading"><h2>Эта неделя</h2><span class="tiny-badge">${streak()} дн.</span></div><div class="week">${weekly()}</div><p class="small muted week-caption">Даже одна попытка — уже практика.</p><div class="daily-time">${icon('clock')}<span>Сегодня <strong>${Math.floor((state.seconds[dateKey()]||0)/60)} из 60 мин</strong></span></div></section></div><div class="bottom-note"><span class="note-icon">${icon('bulb')}</span><p><strong>Сначала твоя попытка.</strong> Решение появится только после ответа. За каждую решённую задачу — 50 XP.</p><button class="text-btn" data-nav="roadmap">Посмотреть весь путь ${icon('arrow')}</button></div>`}
function roadmapPage(){const p=progress(state);return `<div class="page-intro"><div><p class="eyebrow">МАРШРУТ ОБУЧЕНИЯ</p><h1>От «что такое int?» до «я понял»<span class="title-dot">.</span></h1><p class="muted">9 занятий примерно по часу. Можно возвращаться к любой теме.</p></div><span class="outline-tag">${p.completedLessons} / 9 занятий</span></div><div class="roadmap-groups">${['Переменные','Условия','Циклы'].map((topic,group)=>`<section class="roadmap-group card"><div class="group-heading"><div class="topic-symbol">${['{x}','<?>','↻'][group]}</div><div><p class="eyebrow">ГЛАВА 0${group+1}</p><h2>${topic}</h2></div><span class="group-xp">до 450 XP</span></div>${lessons.map((l,i)=>l.topic===topic?`<button class="lesson-row ${done(l)===3?'is-done':''}" data-open="${i}"><span class="lesson-index">${done(l)===3?icon('check'):String(i+1).padStart(2,'0')}</span><span class="lesson-info"><strong>${l.title}</strong><small>${l.subtitle}</small></span><span class="lesson-meta"><span>${done(l)}/3 задачи</span><small>~60 мин</small></span>${icon('arrow')}</button>`:'').join('')}</section>`).join('')}</div><section class="junior-banner"><span class="goal-emblem">${icon('flag')}</span><div><h2>Junior · основы</h2><p>27 задач — твой первый рубеж. Затем: функции, массивы, STL и собственные проекты.</p></div><span class="outline-tag">${p.xp} / 1350 XP</span></section><p class="scope-note">Этот маршрут тренирует чтение кода и понимание основ. Для работы Junior понадобятся дополнительные темы и практика написания программ.</p>`}
function statsPage(){const p=progress(state),next=LEVELS[p.level+1],attempts=Object.values(state.answers).reduce((s,a)=>s+a.attempts,0);return `<div class="page-intro"><div><p class="eyebrow">ТВОИ РЕЗУЛЬТАТЫ</p><h1>Каждая попытка имеет значение<span class="title-dot">.</span></h1><p class="muted">Здесь виден путь, который ты уже прошёл.</p></div><button class="btn btn-outline" id="export">${icon('download')} Скачать прогресс</button></div><div class="stat-grid">${[[icon('bolt'),p.xp,'Всего XP'],[icon('check'),p.solved+'/27','Решено задач'],[icon('book'),p.completedLessons+'/9','Пройдено занятий'],[icon('clock'),Math.floor(Object.values(state.seconds).reduce((s,n)=>s+n,0)/60),'Минут практики']].map(([ic,n,t])=>`<div class="stat-card card"><span class="stat-icon">${ic}</span><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="stats-columns"><section class="card skill-card"><h2>Уверенность по темам</h2><p class="muted small">Прогресс растёт за правильные ответы.</p>${['Переменные','Условия','Циклы'].map(topic=>{const ts=lessons.filter(l=>l.topic===topic).flatMap(l=>l.tasks),count=ts.filter(t=>state.answers[t.id]?.solved).length;return `<div class="skill-row"><div><strong>${topic}</strong><span>${count} / 9 задач</span></div><div class="progress-track"><i style="width:${count/9*100}%"></i></div></div>`}).join('')}<p class="small muted">Всего попыток: ${attempts} · Дней с практикой: ${Object.keys(state.days).length}</p></section><section class="level-card card"><span class="level-big">${icon('spark')}</span><p class="eyebrow">УРОВЕНЬ ${p.level+1} ИЗ 6</p><h2>${LEVELS[p.level].name}</h2><p class="muted">${next?`Ещё ${next.xp-p.xp} XP до уровня «${next.name}».`:'Базовый маршрут завершён. Твой следующий шаг — собственная программа.'}</p><div class="level-ladder">${LEVELS.map((l,i)=>`<div class="ladder-item ${i<=p.level?'reached':''}"><span>${i<=p.level?icon('check'):i+1}</span><strong>${l.name}</strong><small>${l.xp} XP</small></div>`).join('')}</div></section></div><div class="bottom-note">${icon('lock')}<p>Ответы, XP и время сохраняются автоматически в этом браузере. Скачай копию прогресса для себя; синхронизации между устройствами пока нет.</p></div>`}
function highlighted(code){let out='',last=0;const re=/("[^"\n]*"|\b(?:int|double|bool|if|else|for|while|break|continue|true|false)\b|\b\d+(?:\.\d+)?\b|\bcout\b)/g;for(const m of code.matchAll(re)){out+=esc(code.slice(last,m.index));out+=`<span class="${m[0].startsWith('"')?'token-string':/^\d/.test(m[0])?'token-number':m[0]==='cout'?'token-fn':'token-keyword'}">${esc(m[0])}</span>`;last=m.index+m[0].length}return out+esc(code.slice(last))}
function practicePage(){const l=lessons[activeLesson],t=l.tasks[activeTask],a=state.answers[t.id]||{},minutes=Math.floor((state.seconds[dateKey()]||0)/60);return `<button class="back-link" data-nav="today">${icon('back')} Сегодня <span>/ Занятие ${String(activeLesson+1).padStart(2,'0')}</span></button><div class="page-intro practice-intro"><div><p class="eyebrow">${l.topic.toUpperCase()} · ЗАНЯТИЕ ${activeLesson+1} ИЗ 9</p><h1>${l.title}<span class="title-dot">.</span></h1><p class="muted">${l.subtitle}</p></div><button id="timer" class="timer" aria-label="${running?'Приостановить':'Продолжить'} таймер">${icon(running?'pause':'play')} <span id="timer-value">${timerText()}</span><small>/ 60 мин</small></button></div><details class="theory-card card"><summary>${icon('book')} 10 минут на теорию <span>Коротко о главном <b>⌄</b></span></summary><div class="theory-content"><p>${esc(l.theory)}</p><pre>${esc(l.example)}</pre><p class="small muted">Во всех примерах подключён &lt;iostream&gt; и используется пространство имён std. Выполняются строки внутри main().</p></div></details><div class="task-tabs" role="group" aria-label="Задачи занятия">${l.tasks.map((tt,i)=>`<button class="task-tab ${i===activeTask?'selected':''} ${state.answers[tt.id]?.solved?'solved':''}" data-task="${i}" ${i===activeTask?'aria-pressed="true"':'aria-pressed="false"'}><span>${state.answers[tt.id]?.solved?icon('check'):i+1}</span>Задача ${i+1}<small>${state.answers[tt.id]?.solved?'Решена':'+50 XP'}</small></button>`).join('')}</div><section class="task-workspace card"><div class="task-description"><div class="task-kicker"><span>ЧИТАЕМ КОД</span><span>${activeTask+1} / 3</span></div><h2>${t.title}</h2><p class="muted">Что выведет эта программа? Проследи значения переменных и введи результат.</p><div class="code-window"><div class="code-header"><div class="window-dots"><i></i><i></i><i></i></div><span>main.cpp</span><span>C++</span></div><div class="code-body"><div class="line-numbers" aria-hidden="true">${t.code.split('\n').map((_,i)=>`<span>${i+1}</span>`).join('')}</div><pre tabindex="0" aria-label="Код задачи"><code>${highlighted(t.code)}</code></pre></div></div><p class="code-footnote">Фрагмент внутри main() · iostream и std подключены</p></div><div class="answer-pane"><div class="answer-heading"><span>${icon('code')} ТВОЙ ХОД</span><span class="xp-tag">${a.solved?icon('check')+' Решено':'+50 XP'}</span></div><form id="answer-form" novalidate><label for="answer">Вывод программы</label><p id="answer-help" class="small muted">Без кавычек. Регистр важен; лишние пробелы и переносы строк не мешают проверке.</p><div class="answer-field"><span aria-hidden="true">❯</span><textarea id="answer" maxlength="2000" spellcheck="false" autocomplete="off" aria-describedby="answer-help feedback" placeholder="Введи свой ответ…" rows="4">${esc(a.draft||'')}</textarea></div><div id="feedback" role="status" aria-live="polite">${feedbackHTML(a)}</div><button class="btn btn-primary check-btn" type="submit">Проверить ответ ${icon('arrow')}</button><div class="keyboard-hint"><kbd>Ctrl</kbd> + <kbd>Enter</kbd> для проверки</div></form><div class="help-actions"><button class="text-btn" id="hint">${icon('bulb')} ${a.hinted?'Скрыть подсказку':'Подсказка'}</button>${a.attempts?`<button class="text-btn" id="solution">${a.revealed?'Скрыть разбор':'Показать разбор'}</button>`:`<span class="locked-solution">${icon('lock')} Разбор после попытки</span>`}</div>${a.hinted?`<div class="hint-box">${esc(t.hint)}</div>`:''}${a.revealed&&a.attempts?`<div class="solution-box"><strong>Правильный вывод</strong><pre>${esc(t.answer)}</pre><p>${esc(t.explanation)}</p></div>`:''}${a.attempts?`<p class="attempts">Попыток: ${a.attempts}${a.solved?' · XP за задачу уже получен':''}</p>`:''}</div></section><div class="practice-bottom"><span>${done(l)===3?icon('check')+' Все задачи занятия решены. Можно закрепить материал или идти дальше.':'Около 40 минут на задачи + 10 минут на разбор ошибок. Не торопись.'}</span><button class="btn btn-outline" id="next-task">${activeTask<2?'Следующая задача':activeLesson<8?'Следующее занятие':'К моему прогрессу'} ${icon('arrow')}</button></div>${done(l)===3?`<div class="completion-banner">${icon('spark')}<div><strong>Занятие пройдено! 150 XP в твоей копилке.</strong><p>Потрать последние 10 минут на повторение: объясни ход решения своими словами.</p></div></div>`:''}`}
function feedbackHTML(a){if(feedback?.kind==='empty')return '<div class="feedback neutral">Сначала введи ответ. Пустой ответ не считается попыткой.</div>';if(feedback?.kind==='incorrect')return '<div class="feedback incorrect"><strong>Пока не совпало. Попробуй ещё раз.</strong><span>Проследи код построчно. Подсказка и разбор уже доступны.</span></div>';if(feedback?.kind==='correct')return `<div class="feedback correct"><strong>${icon('check')} Верно! ${feedback.xp?'+50 XP':'Задача уже решена'}</strong><span>${feedback.xp?'Отличный шаг вперёд. Ответ сохранён.':'Повторная проверка не добавляет XP.'}</span></div>`;return a.solved?'<div class="feedback correct"><strong>Задача решена · 50 XP получено</strong><span>Можешь повторить её в любое время.</span></div>':''}
function timerText(){const total=state.seconds[dateKey()]||0;return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
function render(){const focus=document.activeElement?.id;$('#app').innerHTML=shell(view==='today'?todayPage():view==='roadmap'?roadmapPage():view==='stats'?statsPage():practicePage());bind();if(focus==='answer'&&view==='practice'){$('#answer').focus();$('#answer').setSelectionRange($('#answer').value.length,$('#answer').value.length)}}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();setView(el.dataset.nav)}));document.querySelectorAll('[data-open]').forEach(el=>el.addEventListener('click',()=>openLesson(Number(el.dataset.open))));document.querySelectorAll('[data-task]').forEach(el=>el.addEventListener('click',()=>{activeTask=Number(el.dataset.task);feedback=null;render()}));$('#timer')?.addEventListener('click',()=>{running=!running;lastTick=Date.now();render()});$('#answer')?.addEventListener('input',e=>{const id=lessons[activeLesson].tasks[activeTask].id;state.answers[id]={...(state.answers[id]||{attempts:0}),draft:e.target.value};feedback=null;$('#feedback').innerHTML='';clearTimeout(saveTimeout);saveTimeout=setTimeout(save,250)});$('#answer')?.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('#answer-form').requestSubmit()}});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();const t=lessons[activeLesson].tasks[activeTask];const oldLevel=progress(state).level;feedback=submitAnswer(state,t.id,$('#answer').value,dateKey());save();render();if(progress(state).level>oldLevel)toast(`Новый уровень: ${LEVELS[progress(state).level].name}!`);$('#feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'})});$('#hint')?.addEventListener('click',()=>{const t=lessons[activeLesson].tasks[activeTask];const a=state.answers[t.id]||{attempts:0};a.hinted=!a.hinted;state.answers[t.id]=a;save();render()});$('#solution')?.addEventListener('click',()=>{const id=lessons[activeLesson].tasks[activeTask].id;if(state.answers[id]?.revealed)state.answers[id].revealed=false;else revealSolution(state,id);save();render()});$('#next-task')?.addEventListener('click',()=>{feedback=null;if(activeTask<2){activeTask++;render();$('.task-tabs').scrollIntoView({block:'start',behavior:'smooth'})}else if(activeLesson<8)openLesson(activeLesson+1);else setView('stats')});$('#export')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({application:'C++ Junior',exportedAt:new Date().toISOString(),summary:progress(state),progress:state},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`cpp-junior-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Копия прогресса скачана')})}
setInterval(()=>{const now=Date.now(),delta=Math.floor((now-lastTick)/1000);if(delta<1)return;lastTick=now;if(view==='practice'&&running&&!document.hidden){const k=dateKey();state.seconds[k]=(state.seconds[k]||0)+Math.min(delta,5);if($('#timer-value'))$('#timer-value').textContent=timerText();save()}},1000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();save()});
window.addEventListener('pagehide',save);
render();
